            <p>由 Claude AI 驱动 · <a href="https://github.com">GitHub</a></p>
        </footer>
    </div>
</body>
</html>
"""

    with open(output_path, "w", encoding="utf-8") as f:
        f.write(html)

    print(f"[完成] 已生成: {output_path}")


def main():
    """主函数"""
    print("=" * 50)
    print("HTML 索引页生成器")
    print("=" * 50)

    config = load_config()
    digests_dir = PROJECT_ROOT / config["output"]["digests_dir"]

