    files = get_digest_files(digests_dir)
    print(f"找到 {len(files)} 份简报")

    output_path = digests_dir / "index.html"
    generate_html(files, output_path)

    print("\n" + "=" * 50)
    print("生成完成!")
    print("=" * 50)


