     5→"""
     6→
     7→import json
     8→import re
     9→from datetime import datetime
    10→from pathlib import Path
    11→
    12→import pytz
    13→
    14→
    15→# 项目根目录
    16→PROJECT_ROOT = Path(__file__).parent.parent
    17→CONFIG_PATH = Path(__file__).parent / "config.json"
    18→
    19→
    20→def load_config() -> dict:
    21→    """加载配置文件"""
    22→    with open(CONFIG_PATH, "r", encoding="utf-8") as f:
    23→        return json.load(f)
    24→
    25→
    26→def get_digest_files(digests_dir: Path) -> list[dict]:
    27→    """获取所有简报文件信息"""
    28→    files = []
    29→    pattern = re.compile(r"^\d{4}-\d{2}-\d{2}\.md$")
    30→
    31→    for file in digests_dir.glob("*.md"):
    32→        if pattern.match(file.name):
    33→            date_str = file.stem
    34→            with open(file, "r", encoding="utf-8") as f:
    35→                content = f.read()
    36→                # 提取第一行作为标题
    37→                first_line = content.split("\n")[0].strip("# ").strip()
    38→
    39→            files.append({
    40→                "date": date_str,
    41→                "filename": file.name,
    42→                "title": first_line or f"{date_str} 科技简报",
    43→                "size": len(content)
    44→            })
    45→
    46→    # 按日期倒序排列
    47→    files.sort(key=lambda x: x["date"], reverse=True)
    48→    return files
    49→
