        }}

        .digest-link {{
            background: var(--accent-color);
            color: white;
            text-decoration: none;
            padding: 0.5rem 1rem;
            border-radius: 6px;
            font-size: 0.9rem;
            transition: opacity 0.2s;
        }}

        .digest-link:hover {{
            opacity: 0.9;
        }}

        .empty {{
            text-align: center;
            padding: 3rem;
            color: #666;
        }}

        footer {{
            text-align: center;
            margin-top: 3rem;
            padding-top: 1.5rem;
            border-top: 1px solid var(--border-color);
            font-size: 0.85rem;
            color: #666;
        }}

        footer a {{
            color: var(--accent-color);
            text-decoration: none;
        }}
    </style>
</head>
