#!/usr/bin/env python3
"""
HTML 索引页生成器
为简报归档生成一个美观的 HTML 索引页面
"""

import json
import re
from datetime import datetime
from pathlib import Path

import pytz


# 项目根目录
PROJECT_ROOT = Path(__file__).parent.parent
CONFIG_PATH = Path(__file__).parent / "config.json"


def load_config() -> dict:
    """加载配置文件"""
    with open(CONFIG_PATH, "r", encoding="utf-8") as f:
        return json.load(f)


def get_digest_files(digests_dir: Path) -> list[dict]:
    """获取所有简报文件信息"""
    files = []
    pattern = re.compile(r"^\d{4}-\d{2}-\d{2}\.md$")

    for file in digests_dir.glob("*.md"):
        if pattern.match(file.name):
            date_str = file.stem
            with open(file, "r", encoding="utf-8") as f:
                content = f.read()
                # 提取第一行作为标题
                first_line = content.split("\n")[0].strip("# ").strip()

            files.append({
                "date": date_str,
                "filename": file.name,
                "title": first_line or f"{date_str} 科技简报",
                "size": len(content)
            })

    # 按日期倒序排列
    files.sort(key=lambda x: x["date"], reverse=True)
    return files


def generate_html(files: list[dict], output_path: Path):
    """生成 HTML 索引页"""
    tz = pytz.timezone("Asia/Shanghai")
    now = datetime.now(tz).strftime("%Y-%m-%d %H:%M:%S")

    html = f"""<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>每日科技简报归档</title>
