            files.append({
                "date": date_str,
                "filename": file.name,
                "title": first_line or f"{date_str} 科技简报",
                "size": len(content)
            })

    # 按日期倒序排列
    files.sort(key=lambda x: x["date"], reverse=True)
    return files


